/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const msg = inputs[0];

const isValid = msg.isDamageRoll && msg?.isAuthor;

return [
  { type: "boolean", value: isValid },
];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const msg = inputs[0];

const isDamageRoll = msg?.isDamageRoll;
const item = msg?.item;
const token = msg?.token;
const rollOptions = msg?.flags?.pf2e?.context?.options;
const outcome = msg?.flags?.pf2e?.context?.outcome;
const isReroll = msg?.isReroll;
const dmgSlugs = msg?.flags?.pf2e?.dice?.filter((d) => d?.enabled)?.map((d) => d?.slug);
const modSlugs = msg?.flags?.pf2e?.modifiers?.filter((d) => d?.enabled)?.map((d) => d?.slug);
const slugs = [item?.slug, dmgSlugs, modSlugs, item?.uuid]?.flat();
const animationList = slugs?.map((slug) => `damage-roll:${slug}`);

const animationName = animationList?.join(", ");
const toolbeltTargets = msg?.flags?.["pf2e-toolbelt"]?.targetHelper?.targets.map(uuid => canvas.tokens.placeables.find(t => t?.document?.uuid === uuid))
let targets = toolbeltTargets?.length > 0 ? toolbeltTargets : (msg?.target ? [msg?.target] : [])
if (targets?.length <= 0) {
  targets = Array.from(msg?.author?.targets ?? 0);
}

return [
  { type: "item", value: item },
  { type: "text", isArray: true, value: rollOptions },
  { type: "outcome", value: outcome },
  { type: "boolean", value: isReroll },
  { type: "text", value: animationName },
  { type: "target", value: token },
  { type: "target", isArray: true, value: targets },
  { type: "text", isArray: true, value: slugs}
];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const update = inputs[0];
const userID = inputs[1];

const value = Number.isInteger(update?.system?.badge?.value) || Number.isInteger(update?.system?.value?.value)

return [
  {type: "boolean", value: value && game.user.id === userID}
];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const actor = inputs[0]?.actor;
const update = inputs[1];

const itemID = update?.system?.exploration?.find(i => !actor?.system?.exploration?.includes(i))

return [
  {type: "boolean", value: update?.system?.exploration?.length >= actor?.system?.exploration?.length},
  {type: "item", value: actor?.items?.get(itemID)},
  {type: "target", isArray: true, value: actor ? actor?.getActiveTokens() : []},
  {type: "text", isArray: true, value: actor ? Object.keys(actor?.rollOptions?.all) : []},
];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const msg = inputs[0]

return [{type: "boolean", value: msg?.flags['pf2e-hud']?.action === 'recall-knowledge' || msg?.flags?.pf2e?.context?.options?.some(r => r === 'action:recall-knowledge')}, {type: "target", value: msg?.token ?? msg?.actor}, {type: "text", isArray: true, value: msg?.flags?.pf2e?.context?.options ?? []}];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const update = inputs[0];
const item = inputs[1];
const preAmmo = item?.system?.subitems?.find(it => it?.type === 'ammo') || null
const value = update?.system?.subitems?.find(it => it?.type === 'ammo') || null

return [{type: "boolean", value: !!value && !preAmmo}, {type: "text", value: value?.system?.slug ?? ''}, {type: "text", isArray: true, value: value?.system?.traits?.value ?? ''},{type: "number", value: value?.system?.quantity ?? 0}];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const update = inputs[0];
const userID = inputs[1];

const rollOption = update?.system?.rules?.find(rule => rule?.value && rule?.key === 'RollOption')

return [
  {type: "boolean", value: !!rollOption && game.user.id === userID},
  {type: "text", value: rollOption?.selection ?? ''},
  {type: "text", value: rollOption?.option ?? ''}
];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const options = inputs[0];
const names = options.filter(ro => ro.startsWith("action:")).join(', ')
return [{type: "text", value: names}];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const msg = inputs[0];

return [
  { type: "boolean", value: 
    msg?.item?.type === 'spell'
    && !msg?.isRoll
    && !msg?.flags?.pf2e?.appliedDamage
    && msg?.token
  },
];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const msg = inputs[0];

const isDamageRoll = msg?.isDamageRoll;
const item = msg?.item;
const token = msg?.token;
const rollOptions = [msg?.flags?.pf2e?.origin?.rollOptions, Object.keys(msg?.actor?.rollOptions?.all)].flat();
const slug = msg?.item?.slug ?? game?.pf2e?.system?.sluggify(msg?.item?.name)
const uuid = msg?.item?.uuid;

const toolbeltTargets = msg?.flags?.["pf2e-toolbelt"]?.targetHelper?.targets.map(uuid => canvas.tokens.placeables.find(t => t?.document?.uuid === uuid))
let targets = toolbeltTargets?.length > 0 ? toolbeltTargets : (msg?.target ? [msg?.target] : [])
if (targets?.length <= 0) {
  targets = Array.from(msg?.author?.targets ?? 0);
}


return [
  { type: "text", value: slug },
  { type: "target", value: token },
  { type: "target", isArray: true, value: targets },
  { type: "item", value: item },
  { type: "text", isArray: true, value: rollOptions },
  { type: "text", value: uuid },
];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
const combatant = inputs[0];
const token = combatant?.token;
const actor = combatant?.actor;
const {condition} = actor?.items?.documentsByType;
const rollOptions = Object.keys(actor?.rollOptions?.all)
return [
  {type: "target", value: actor},
  {type: "item", isArray: true, value: condition},
  {type: "text", isArray: true, value: rollOptions},
];

/**
 * @param {unknown[]} inputs
 * @returns {boolean} to break out current process
 * @returns {{type: EntryType; value: unknown}[]}
 *
 * @example
 * const x = inputs[0];
 * const y = inputs[1];
 * return [{type: "number", value: x + y}];
 */
let cnt = inputs[0] ?? 0;
const conditions = inputs[1] ?? [];
const condition = conditions?.[cnt];

cnt++;
return [{type: "item", value: condition}, {type: "number", value: cnt}];
